// ESM dependency: uses a STATIC named import of a mediated builtin. Under capwall's M5 ESM
// hook this import binds to the fs shim, so readFromDep() is attributed to "esm-fixture-dep".
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
const DATA = fileURLToPath(new URL("./data.txt", import.meta.url));
export function readFromDep() {
  return readFileSync(DATA, "utf8");
}
